import sys

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
        self.height = 1

def get_height(node):
    if node is None:
        return 0
    return node.height

def get_balance(node):
    if node is None:
        return 0
    return get_height(node.left) - get_height(node.right)

def update_height(node):
    if node:
        node.height = 1 + max(get_height(node.left), get_height(node.right))

def right_rotate(y):
    x = y.left
    y.left = x.right
    x.right = y
    update_height(y)
    update_height(x)
    return x

def left_rotate(x):
    y = x.right
    x.right = y.left
    y.left = x
    update_height(x)
    update_height(y)
    return y

def insert(node, value):
    if node is None:
        return Node(value)

    if value < node.value:
        node.left = insert(node.left, value)
    elif value > node.value:
        node.right = insert(node.right, value)
    else:
        return node

    update_height(node)
    balance = get_balance(node)

    # LL case
    if balance > 1:
        if value < node.left.value:
            print(f"LL Rotation at node {node.value}")
            return right_rotate(node)
        else:
            print(f"LR Rotation at node {node.value}")
            node.left = left_rotate(node.left)
            return right_rotate(node)

    # RR case
    if balance < -1:
        if value > node.right.value:
            print(f"RR Rotation at node {node.value}")
            return left_rotate(node)
        else:
            print(f"RL Rotation at node {node.value}")
            node.right = right_rotate(node.right)
            return left_rotate(node)

    return node

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        return
    values = list(map(int, data[1:n+1]))

    root = None
    for val in values:
        root = insert(root, val)

if __name__ == "__main__":
    main()
